const fs=require('fs'),path=require('path'),{chromium}=require('playwright');const a=process.argv.slice(2),arg=(n,f='')=>{const i=a.indexOf(n);return i>=0&&a[i+1]?a[i+1]:f};const base=arg('--url','http://localhost/greenportal').replace(/\/$/,''),empresa=arg('--empresa','Modelo'),usuario=arg('--usuario','admin'),senha=arg('--senha', process.env.GREEN_TEST_PASSWORD || ''),cdp=arg('--cdp',''),out=path.resolve(arg('--saida','tests/resultado-pdf-requisitos-legais-20260924.json'));const result={startedAt:new Date().toISOString(),checks:[],status:'REPROVADO'};const check=(n,o,d='')=>{result.checks.push({name:n,ok:!!o,details:d});console.log(`${o?'PASS':'FAIL'} - ${n}${d?`: ${d}`:''}`);if(!o)throw new Error(n)};async function main(){let b;try{b=cdp?await chromium.connectOverCDP(cdp):await chromium.launch({headless:true});const c=cdp?(b.contexts()[0]||await b.newContext()):await b.newContext({viewport:{width:1440,height:900}});const p=cdp?(c.pages()[0]||await c.newPage()):await c.newPage({viewport:{width:1440,height:900}});p.setDefaultTimeout(20000);await p.goto(base+'/index.php',{waitUntil:'domcontentloaded'});await p.locator('#empresa').selectOption({label:empresa}).catch(()=>p.locator('#empresa').selectOption({value:empresa}));await p.locator('#userid').fill(usuario);await p.locator('#senha').fill(senha);await p.locator('form.login-form button[type="submit"]').click();await p.waitForURL(/\/principal\/main\.php/);await p.locator('[data-sidebar-toggle]').click().catch(()=>{});await p.locator('#menuSearch').fill('Requisitos legais');await p.locator('button[data-open-tab][data-tab-url*="modulolegal_requisitoslegais.php"]').click();const f=p.frameLocator('iframe[src*="modulolegal_requisitoslegais.php"]');await f.locator('#requisitosLegaisBatchGrid tbody tr').first().waitFor({state:'visible'});const row=f.locator('#requisitosLegaisBatchGrid tbody tr').first();const code=(await row.locator('[data-column="CODIGO"]').innerText()).trim();const icon=row.locator('[data-open-legislacao-pdf]').first();check('Ícone PDF presente na linha',await icon.count()===1,code);const pdfUrl=base+'/principal/legislacao_pdf.php?codigo='+encodeURIComponent(code);const pdfResponse=await p.request.get(pdfUrl);const pdfBody=await pdfResponse.body();check('Endpoint PDF HTTP 200',pdfResponse.status()===200,`HTTP ${pdfResponse.status()}`);check('Resposta PDF não vazia',pdfBody.length>100,`${pdfBody.length} bytes`);check('Resposta possui assinatura PDF',pdfBody.subarray(0,5).toString()==='%PDF-',pdfBody.subarray(0,5).toString());await row.click();await icon.click({force:true});await p.waitForTimeout(1000);const inside=f.locator('#requisitosPdfModal');const outside=p.locator('#requisitosPdfModal');const insideCount=await inside.count(),outsideCount=await outside.count();const modal=insideCount?inside:outside;check('Modal PDF criado visualmente',insideCount+outsideCount>0,`iframe=${insideCount},pagina=${outsideCount}`);const shown=await modal.isVisible().catch(()=>false);check('Modal PDF visível',shown);const frameSrc=await modal.locator('[data-requisitos-pdf-frame]').getAttribute('src').catch(()=>null);check('Iframe do modal aponta para PDF',/legislacao_pdf\.php\?codigo=/i.test(frameSrc||''),frameSrc||'');result.code=code;result.pdfBytes=pdfBody.length;result.status='APROVADO'}catch(e){result.error=e.message;throw e}finally{result.finishedAt=new Date().toISOString();fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,JSON.stringify(result,null,2));if(b&&!cdp)await b.close()}}main().catch(e=>{console.error(`ERRO FATAL: ${e.stack||e.message}`);process.exit(1)});
